//线程
wg = sync.NewSizedWaitGroup(thread)

//转换插件读取的json字符串为map[string]string类型
setHeaders = func(h){
    mapHeaders = make(map[string]string)
    for k,v = range json.loads(h){
        mapHeaders[k] = v
    }
    return mapHeaders
}
//打印字典扫描记录
count = 0
//响应成功的记录
successCount = 0
mux = sync.NewLock()

statusAddCount = func() {
    mux.Lock()
    defer mux.Unlock()
    count++
    yakit.StatusCard("5、扫描", str.f("%v", count))
}
statusAddSuccessCount = func() {
    mux.Lock()
    defer mux.Unlock()
    successCount++
    yakit.StatusCard("6、成功", str.f("%v", successCount))
}

//记录响应出现的次数,
mux2 = sync.NewLock()
bodynum = make(map[string]int)
AddBodynum = func(md5){
    result =false
    mux2.Lock()
    defer mux2.Unlock()
    if !bodynum[md5]{
        bodynum[md5] = 1
        result=true
    }
    return result
}

//打印目录爆破结果
yakit.EnableTable("目录爆破", ["url","status","title","length"])
outDirTable = func(url,status,title,length){
    d = make(map[string]var)
    d["url"] = url
    d["status"] = status
    d["title"] = title
    d["length"] = length
    yakit.TableData("目录爆破", d)
    statusAddSuccessCount()
}

//打印提取的敏感信息
yakit.EnableTable("敏感信息", ["url","type","data"])
outSensitiveInfoTable = func(path,t,data){
    d = make(map[string]var)
    d["url"] = path
    d["type"] = t
    d["data"] = data
    yakit.TableData("敏感信息", d)
}

//打印提取的路由信息
yakit.EnableTable("路由信息", ["domain","type","data"])
outPathInfoTable = func(domain,t,data){
    d = make(map[string]var)
    d["domain"] = domain
    d["type"] = t
    d["data"] = data
    yakit.TableData("路由信息", d)
}
// 指定正则，响应中匹配的结果
extractInfo = func(respRaw,pattern){
    result = re.FindAll(respRaw, pattern)
    return result
}

//获取body
getResqRaw = func(url){
    res, req ,err = poc.Get(url, poc.timeout(5), poc.appendHeaders(setHeaders(headers)))
    if err != nil{
        yakit.Error("%v :访问失败！"%url)
        return ""
    }
    body = res.GetBody()
    return body
}



//随机访问一个路径，记录body，用作和后面的字典扫描做相似度对比
randomReqPath = func(url){
    s = randstr(5)
    if str.EndsWith(url,"/"){
        url = url + s
    }else{
        url = url + '/' +s
    }
    res, _,err  = poc.Get(url, poc.timeout(5),poc.appendHeaders(setHeaders(headers)))
    if err != nil{
        yakit.Error("url:%v"%"请求失败!")
        return ""
    }
    return res.GetBody()
}
//解析url
parseUrl = func(url){
    protocol = str.Split(url, "//")[0]
    hostPort = str.Split(url, "//")[1]
    if "/" in hostPort{
        hostPort = str.Split(hostPort, "/")[0]
    }else if "#" in hostPort{
        hostPort = str.Split(hostPort, "#")[0]
    }
    if "#" in hostPort{
        hostPort = str.Split(hostPort, "#")[0]
    }
    return protocol,hostPort
}


//打印爬取到指定域的链接
printCrawlerPath2 = func(domain,crawlerPath2){
    if len(crawlerPath2) != 0{
        for _,v = range crawlerPath2{
            if domain in v{
                outPathInfoTable(domain,"url", v)
            }else if v.StartsWith("/") && !v.StartsWith("//"){
                outPathInfoTable(domain,"path",v)
            }
        }
    }
}

//爬取信息
crawlerInfo = func(url){
    //爬取过的js、html、shtml、htm路劲
    crawlerPath = []string{}
    //爬取到的路径
    crawlerPath2 = []string{}
    if !url.StartsWith("http"){
        yakit.Info("url:%v 错误"%url)
        return 
    }
    protocol,domain = parseUrl(url)
    tmpList = []string{url}
    for i = range depth{
        jsList = []string{}
        for len(tmpList)!=0{
            u = tmpList.Pop()
            if u in crawlerPath{
                continue
            }
            crawlerPath = append(crawlerPath, u)
            yakit.Info("爬取：%v"%u)
            body = getResqRaw(u)
            for _,v = range SensitiveInfo{
                r = extractInfo(body,SensitiveInfoConfig[v])
                if len(r) != 0{
                    for _,v1 = range r{
                        outSensitiveInfoTable(u,v,v1)
                    }
                }
            }
            for k,v = range UrlConfig{
                r1 = extractInfo(body,v)
                if len(r1)!=0{
                    for _,v1 = range r1{
                        result = ""
                        if k == "url"{
                            result = str.TrimSpace(v1[:-1])
                        }else if  k == "path"{
                            result = str.TrimSpace(v1[1:-1])
                            if str.StartsWith(result, "./"){
                                result = result[1:]
                            }else if (!str.StartsWith(result, "./"))&& (!str.StartsWith(result, "/")){
                                result = "/" + result
                            }
                        }
                        if result in crawlerPath2{
                            continue
                        }
                        crawlerPath2 = append(crawlerPath2, result)
                        for _,fileEnd = range crawlerFileName{
                            if fileEnd in result{
                                if result.StartsWith("http") && domain in result{
                                    jsList = append(jsList, result)
                                }else if result.StartsWith("//")  && domain in result{
                                    jsList = append(jsList, protocol+result)
                                }else if k=="path"{
                                    jsList = append(jsList,protocol+"//"+domain+result)
                                }
                                break
                            }
                        }
                    }
                }
            }
        }
        tmpList = jsList
    }
    printCrawlerPath2(domain,crawlerPath2)
    return crawlerPath2
}
//提取第一个路径
extractOnePath = func(path){
    if str.StartsWith(path, "http") || str.StartsWith(path, "//"){
        tmp = re.Find(path, "[^/]/[^/].*?/")
        if len(tmp)>=4{
            return tmp[1:-1]
        }
    }else if str.StartsWith(path, "/"){
        tmp = re.Find(path, "/[^/].*?/")
        if len(tmp)>=3{
            return tmp[0:-1]
        }
    }else{
        return ""
    }
}


//从爬取的所有接口中，提取第一个路径
extractAllOnePath = func(pathList,domain){
    //存储提取第一个路径
    extractOnePathList = []string{}
    for _, v = range pathList{
        if (v.StartsWith("http") || v.StartsWith("//"))&& !(domain in v){
            continue
        }
        onePath = extractOnePath(v)
        if  onePath != "" && !(onePath in extractOnePathList){
            extractOnePathList.Push(onePath)
        }
    }
    yakit.Info("一级路由数：%v"%len(extractOnePathList))
    yakit.Info("一级路由：%v", str.Join(extractOnePathList, " "))
    return extractOnePathList
}

//解析输入的状态码参数
parseStatus = func(){
    StatusList = str.Split(showStatu,",")
    intStatus  = make([]int)
    try{
        for _,v = range StatusList{
            intStatus.Push(int(v))
        }
    }catch{
        yakit.Error("状态码输入格式错误，请输入阿拉伯数字并用逗号分隔")
        os.Exit(0)
    }
    return intStatus
}

//生成字典
genDict = func(extractOnePathList){
    Dicts = str.ParseStringToLines(dirDict)
    if len(dirTempDict)>0{
        tmpDict = str.ParseStringToLines(dirTempDict)
        Dicts = append(Dicts, tmpDict...)
    }
    if DictFile != []{
        tmpDictFile = str.ParseStringToLines(string(DictFile))
        Dicts = append(Dicts, tmpDictFile...)
    }
    if len(Dicts) == 0{
        yakit.Info("字典数为0")
        os.Exit(0)
    }
    if !crawlerStart{
        return Dicts
    }
    result = make([]string)
    result = append(result, Dicts...)
    for _,path = range extractOnePathList{
        for _,dict = range Dicts{
            result.Push(path+dict)
        }
    }
    return result
}

//检查网站存活
checkSurvival = func(url){
    yakit.Info("检查存活：%v"%url)
    if !str.IsHttpURL(url){
        yakit.Error("url:%v 格式不正确"%url)
        return false
    }
    res,_,err = poc.Get(url, poc.timeout(5),poc.appendHeaders(setHeaders(headers)))
    if err != nil{
        yakit.Error("%v 未存活"%url)
        return false
    }
    return true
}


main = func(){
    scanDictLen = 0
    targets = str.ParseStringToLines(targets)
    yakit.StatusCard("2、总数", str.f("%v", len(targets)))
    yakit.StatusCard("3、完成", str.f("%v",0))
    yakit.StatusCard("5、扫描", str.f("%v", 0))
    yakit.StatusCard("6、成功", str.f("%v", 0))
    yakit.StatusCard("4、字典", str.f("%v", 0))
    for v,target = range targets{
        yakit.StatusCard("1、当前", target)
        target = str.TrimSpace(target)
        if !checkSurvival(target){continue}
        statusList = parseStatus()
        println(parseStatus)
        // randomBody = randomReqPath(target)
        protocol,domain = parseUrl(target)


        if crawlerStart{
            crawlerPath2 = crawlerInfo(target)
            OnePaths=extractAllOnePath(crawlerPath2,domain)
            dicts = genDict(OnePaths)
            scanDictLen = scanDictLen + len(dicts)
            yakit.StatusCard("4、字典", scanDictLen)
            for _,dict := range dicts{
                dict := dict
                wg.Add()
                go fn{
                    defer wg.Done()
                    url = protocol + "//" + domain +dict
                    res,_,err = poc.Get(url, poc.timeout(5),poc.appendHeaders(setHeaders(headers)))
                    statusAddCount()
                    if err != nil{
                        log.Info("url:%v 请求失败"%url)
                        return
                    }
                    body = res.GetBody()
                    // if str.CalcSimilarity(randomBody,body) > 0.9{
                    //     return
                    // }
                    statusCode = res.GetStatusCode()
                    if !(statusCode in statusList){
                        // yakit.Info("%v"%statusCode)
                        return
                    }
                    length = len(body)
                    title = str.ExtractTitle(body)
                    //记录当前请求的长度，长度相同的过滤不显示
                    md5 = codec.Md5(domain+"%v"%length)
                    if length >0 && AddBodynum(md5) {
                        outDirTable(url, statusCode, title, length)
                    }
                }
            }

        }else{
                dicts = genDict([])
                scanDictLen = scanDictLen + len(dicts)
                yakit.StatusCard("4、字典", scanDictLen)
                for _,dict := range dicts{
                    dict := dict
                    wg.Add()
                    go fn{
                        defer wg.Done()
                        url = protocol + "//" + domain +dict
                        res,_,err = poc.Get(url, poc.timeout(5),poc.appendHeaders(setHeaders(headers)))
                        statusAddCount()
                        if err != nil{
                            log.Info("url:%v 请求失败"%url)
                            return
                        }
                        body = res.GetBody()
                        // if str.CalcSimilarity(randomBody,body) > 0.9{
                        //     return
                        // }
                        statusCode = res.GetStatusCode()
                        if !(statusCode in statusList){
                        return
                        }
                        length = len(body)
                        title = str.ExtractTitle(body)
                        md5 = codec.Md5(domain+"%v"%length)
                        if length >0 && AddBodynum(md5){
                            outDirTable(url, statusCode, title, length)
                        }
                    }
                }
        }
        yakit.StatusCard("3、完成", str.f("%v",v+1))
    }
    wg.Wait()
}


main()
